import fcntl,json,math,sys,time
sys.path.insert(0,"/home/nvidia/tianji-robot-SDK/PYTHON_SDK")
from GentoRobot import GentoRobot
settings=json.loads(sys.argv[1]); home=json.loads(sys.argv[2])
objects={"arm0":0,"arm1":1,"body":3}
def emit(event,**data):
 print(json.dumps(dict(event=event,**data)),flush=True)
def read(robot):
 if robot.check_link_state()!=1: raise RuntimeError("SDK link lost")
 rt,sg=robot.get_rt_dict(),robot.get_sg_dict()
 poses={}; ratios={}; modes={}
 for key,obj in objects.items():
  raw=rt['body'] if key=='body' else rt['arms'][obj]
  fb=raw if key=='body' else raw['fb']
  cfg=sg['body'] if key=='body' else sg['arms'][obj]
  if raw['state']['err'] or raw['state']['cur'] not in (0,1): raise RuntimeError('Unexpected state: '+key)
  if cfg['get']['traj_state'] not in (0,1,2): raise RuntimeError('Trajectory active: '+key)
  for field in ('fb_pos','fb_vel','cmd_pos'):
   if len(fb[field])!=len(home[key]) or not all(math.isfinite(v) for v in fb[field]): raise RuntimeError('Invalid feedback: '+key)
  if max(map(abs,fb['fb_vel']))>.15: raise RuntimeError('Moving: '+key)
  if max(abs(a-b) for a,b in zip(fb['fb_pos'],home[key]))>.05: raise RuntimeError('Not at HOME: '+key)
  if max(abs(a-b) for a,b in zip(fb['fb_pos'],fb['cmd_pos']))>.05: raise RuntimeError('Pending position target: '+key)
  poses[key]=fb['fb_pos']; modes[key]=raw['state']['cur']
  ratios[key]={k:cfg['set'][k] for k in ('vel_ratio','acc_ratio')}
 return {'frame':rt['frame_serial'],'pose':poses,'modes':modes,'ratios':ratios}
with open('/tmp/gento_sdk_6_6_7_190.lock','a+') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 robot=GentoRobot()
 try:
  result=robot.link(6,6,7,190)
  if not robot._connected: raise RuntimeError('SDK link failed: '+str(result))
  samples=[]
  for _ in range(5):
   time.sleep(.2); samples.append(read(robot))
  if len({s['frame'] for s in samples})!=5: raise RuntimeError('Feedback frames not fresh')
  baseline=samples[-1]
  emit('ratios_before',sample=baseline)
  for key,obj in objects.items():
   before=read(robot)
   if before['modes']!=baseline['modes']: raise RuntimeError('Mode changed')
   config=settings[key]
   result=robot.runtime_set_speed_ratio(obj,config['speed_percent'],config['acceleration_percent'])
   emit('ratio_write',group=key,requested=config,return_code=result)
   if result!=0: raise RuntimeError('Ratio write failed: '+key)
   deadline=time.monotonic()+2.
   confirmed=[]
   while True:
    time.sleep(.05); sample=read(robot)
    if sample['modes']!=baseline['modes']: raise RuntimeError('Mode changed')
    values=sample['ratios'][key]
    match=all(math.isfinite(values[k]) and abs(values[k]-config[v])<=.1 for k,v in (('vel_ratio','speed_percent'),('acc_ratio','acceleration_percent')))
    if match and sample['frame'] not in confirmed: confirmed.append(sample['frame'])
    if not match: confirmed=[]
    if len(confirmed)>=3: break
    if time.monotonic()>deadline: raise RuntimeError('Ratio readback timeout: '+key)
   emit('ratio_confirmed',group=key,readback=sample['ratios'][key],frames=confirmed)
  final=read(robot)
  for key,config in settings.items():
   for field,param in (('vel_ratio','speed_percent'),('acc_ratio','acceleration_percent')):
    value=final['ratios'][key][field]
    if not math.isfinite(value) or abs(value-config[param])>.1: raise RuntimeError('Final ratio mismatch: '+key)
  if final['modes']!=baseline['modes']: raise RuntimeError('Final mode changed')
  emit('ratios_restored',sample=final,motion_commands_sent=0,mode_changes_sent=0)
 finally:
  if robot._connected: robot.unlink(); emit('sdk_disconnected')

